public str getName()
{
    return fieldPName(InventItemGroupItem, ItemGroupDataAreaId);
}

public Set getAllowedValues()
{
    var                 ret = new Set(Types::String);
    InventItemGroupItem inventItemGroupItem;

    while select inventItemGroupItem
        group by ItemGroupDataAreaId
    {
        if (! ret.in(inventItemGroupItem.ItemGroupDataAreaId))
        {
            ret.add(inventItemGroupItem.ItemGroupDataAreaId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventItemGroupItem, ItemGroupDataAreaId));
    qbr.value(queryValue(_value));
}
